import{_ as r,C as s,o as e,c as o,a2 as l,b as a,w as n,a as g,E as i,a3 as c}from"./chunks/framework.BBdhqAg0.js";const x="data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mNkYAAAAAYAAjCB0C8AAAAASUVORK5CYII=",p=JSON.parse('{"title":"차수 타입 설정","description":"","frontmatter":{},"headers":[],"relativePath":"project/types.md","filePath":"project/types.md","lastUpdated":1793112345000}'),y={name:"project/types.md"};function A(B,t,E,f,h,C){const d=s("Mermaid");return e(),o("div",null,[t[1]||(t[1]=l('<h1 id="차수-타입-설정" tabindex="-1">차수 타입 설정 <a class="header-anchor" href="#차수-타입-설정" aria-label="Permalink to &quot;차수 타입 설정&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">📸 실제 화면 안내</p><p><img src="'+x+'" alt="차수 및 타입 설정 화면"><em>관리자 참고: 해당 화면의 실제 캡처 이미지를 <code>./images/types.png</code> 경로에 등록해 주세요.</em></p></div><blockquote><p><strong>차수 타입 설정</strong>은 프로젝트의 계약 차수(조합원 모집, 1차 분양, 일반 분양 등)와 공급 평형별 세부 타입(59A, 84B 등), 그리고 층별 차등가 적용을 위한 층별 범위를 등록하는 기준 정보 관리 모듈입니다.</p></blockquote><ul><li><strong>접근 경로</strong>: 시스템 좌측 내비게이션 메뉴에서 **[PJT 관리 시스템] → [프로젝트 설정] → [차수 타입 설정]**을 선택하여 접속합니다.</li></ul>',4)),(e(),a(c,null,{default:n(()=>[i(d,{id:"mermaid-20",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20A%5B%221.%20%EC%B0%A8%EC%88%98%20%EB%B6%84%EB%A5%98%20%EB%93%B1%EB%A1%9D%3Cbr%3E(%EC%A1%B0%ED%95%A9%EC%9B%90%2F%EC%9D%BC%EB%B0%98%EB%B6%84%EC%96%91%20%EA%B5%AC%EB%B6%84)%22%5D%20--%3E%20D%5B%22%F0%9F%8F%A2%20%EA%B3%B5%EA%B8%89%20%EA%B0%80%EA%B2%A9%20%26%20%EC%9C%A0%EB%8B%9B%20%EC%83%9D%EC%84%B1%22%5D%0A%20%20%20%20B%5B%222.%20%ED%83%80%EC%9E%85%20%EC%A0%95%EB%B3%B4%20%EB%93%B1%EB%A1%9D%3Cbr%3E(%ED%8F%89%ED%98%95%C2%B7%EB%A9%B4%EC%A0%81%C2%B7%EA%B3%A0%EC%9C%A0%20%EC%83%89%EC%83%81)%22%5D%20--%3E%20D%0A%20%20%20%20C%5B%223.%20%EC%B8%B5%EB%B3%84%20%EC%A1%B0%EA%B1%B4%20%EB%93%B1%EB%A1%9D%3Cbr%3E(%EC%A0%80%EC%B8%B5%2F%EA%B8%B0%EC%A4%80%EC%B8%B5%2F%EC%B5%9C%EC%83%81%EC%B8%B5%20%EB%B2%94%EC%9C%84)%22%5D%20--%3E%20D%0A"})]),fallback:n(()=>[...t[0]||(t[0]=[g(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=l('<h2 id="_1-차수-분류-등록" tabindex="-1">1. 차수 분류 등록 <a class="header-anchor" href="#_1-차수-분류-등록" aria-label="Permalink to &quot;1. 차수 분류 등록&quot;">​</a></h2><p>프로젝트의 계약 진행 단계에 따른 차수 그룹을 등록합니다. 이 정보는 향후 계약 등록 및 분양가 산정 시 기준으로 활용됩니다.</p><ul><li><strong>위치</strong>: <code>프로젝트 설정 &gt; 차수 타입 설정 &gt; 차수 분류 등록</code></li></ul><table tabindex="0"><thead><tr><th style="text-align:left;">라벨</th><th style="text-align:center;">필수입력</th><th style="text-align:left;">상세 설명 및 실무 기준</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>등록차수</strong></td><td style="text-align:center;"><strong>필수</strong></td><td style="text-align:left;">해당 차수의 순서(회차)를 숫자로 입력 (예: <code>1</code>, <code>2</code>)</td></tr><tr><td style="text-align:left;"><strong>차수구분</strong></td><td style="text-align:center;"><strong>필수</strong></td><td style="text-align:left;"><code>조합모집</code> 또는 <code>일반분양</code> 중 선택</td></tr><tr><td style="text-align:left;"><strong>차수그룹명</strong></td><td style="text-align:center;"><strong>필수</strong></td><td style="text-align:left;">차수를 식별할 수 있는 명칭 (예: <code>1차 조합원 모집</code>, <code>일반분양분</code>)</td></tr><tr><td style="text-align:left;"><strong>미계약세대 기본설정</strong></td><td style="text-align:center;"></td><td style="text-align:left;">미계약 세대 공급가격 생성 시 기본 적용할 차수 (프로젝트당 1개만 설정 가능)</td></tr></tbody></table><h2 id="_2-타입-정보-등록" tabindex="-1">2. 타입 정보 등록 <a class="header-anchor" href="#_2-타입-정보-등록" aria-label="Permalink to &quot;2. 타입 정보 등록&quot;">​</a></h2><p>공급 시설의 타입(평형)별 세부 정보를 등록하고 면적 및 가격 책정 방식을 정의합니다.</p><ul><li><strong>위치</strong>: <code>프로젝트 설정 &gt; 차수 타입 설정 &gt; 타입 정보 등록</code></li></ul><table tabindex="0"><thead><tr><th style="text-align:left;">라벨</th><th style="text-align:center;">필수입력</th><th style="text-align:left;">상세 설명 및 실무 기준</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>타입종류</strong></td><td style="text-align:center;"><strong>필수</strong></td><td style="text-align:left;">공동주택, 오피스텔, 숙박시설, 근린생활시설 등 시설 용도 선택</td></tr><tr><td style="text-align:left;"><strong>타입구분</strong></td><td style="text-align:center;"><strong>필수</strong></td><td style="text-align:left;"><code>메인유닛</code>(주거 세대) 또는 <code>보조시설</code>(창고, 주차장 등) 여부 선택</td></tr><tr><td style="text-align:left;"><strong>타입명칭</strong></td><td style="text-align:center;"><strong>필수</strong></td><td style="text-align:left;">타입을 식별하는 공식 명칭 (예: <code>59A</code>, <code>84B</code>, <code>114P</code>)</td></tr><tr><td style="text-align:left;"><strong>타입색상</strong></td><td style="text-align:center;"><strong>필수</strong></td><td style="text-align:left;"><strong>동호수 배치도(유닛 현황판) 등에서 타입을 구분하기 위한 전용 색상</strong> 지정</td></tr><tr><td style="text-align:left;"><strong>전용면적</strong></td><td style="text-align:center;"></td><td style="text-align:left;">전용면적 (제곱미터, ㎡)</td></tr><tr><td style="text-align:left;"><strong>공급면적</strong></td><td style="text-align:center;"></td><td style="text-align:left;">공급면적 (제곱미터, ㎡)</td></tr><tr><td style="text-align:left;"><strong>계약면적</strong></td><td style="text-align:center;"></td><td style="text-align:left;">계약면적 (제곱미터, ㎡)</td></tr><tr><td style="text-align:left;"><strong>평균가격</strong></td><td style="text-align:center;"></td><td style="text-align:left;">해당 타입의 기준 평균 분양가격 (예산 미수립 시 초기 단가로 활용)</td></tr><tr><td style="text-align:left;"><strong>공급가 설정 옵션</strong></td><td style="text-align:center;"><strong>필수</strong></td><td style="text-align:left;">가격 책정 기준 (<code>타입별</code> / <code>층타입별</code> / <code>호별 설정</code> 중 선택)</td></tr><tr><td style="text-align:left;"><strong>세대수</strong></td><td style="text-align:center;"><strong>필수</strong></td><td style="text-align:left;">해당 타입으로 공급되는 총 세대수</td></tr></tbody></table><h2 id="_3-층별-조건-등록" tabindex="-1">3. 층별 조건 등록 <a class="header-anchor" href="#_3-층별-조건-등록" aria-label="Permalink to &quot;3. 층별 조건 등록&quot;">​</a></h2><p>층별로 분양가를 다르게 적용(층별 차등 분양가)하기 위한 층 범위를 설정합니다. 이 설정은 타입 정보 등록에서 &#39;층타입별 설정&#39;을 선택한 경우에 적용됩니다.</p><ul><li><strong>위치</strong>: <code>프로젝트 설정 &gt; 차수 타입 설정 &gt; 층별 조건 등록</code></li></ul><table tabindex="0"><thead><tr><th style="text-align:left;">라벨</th><th style="text-align:center;">필수입력</th><th style="text-align:left;">상세 설명 및 실무 기준</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>타입종류</strong></td><td style="text-align:center;"><strong>필수</strong></td><td style="text-align:left;">층 조건을 적용할 시설 용도 선택 (공동주택 등)</td></tr><tr><td style="text-align:left;"><strong>시작 층</strong></td><td style="text-align:center;"><strong>필수</strong></td><td style="text-align:left;">범위의 시작 층 (지하층은 -1 이하 숫자로 입력)</td></tr><tr><td style="text-align:left;"><strong>종료 층</strong></td><td style="text-align:center;"><strong>필수</strong></td><td style="text-align:left;">범위의 종료 층</td></tr><tr><td style="text-align:left;"><strong>방향/위치(선택)</strong></td><td style="text-align:center;"></td><td style="text-align:left;">조망권, 향(동/서/남/북)이나 라인 등 추가 구분 조건 입력</td></tr><tr><td style="text-align:left;"><strong>층별 범위 명칭</strong></td><td style="text-align:center;"><strong>필수</strong></td><td style="text-align:left;">해당 범위를 식별할 명칭 (예: <code>1~3층(저층부)</code>, <code>4~19층(기준층)</code>, <code>20층 이상(로열층)</code>)</td></tr></tbody></table><h2 id="_4-신입사원을-위한-실무-가이드" tabindex="-1">4. 신입사원을 위한 실무 가이드 <a class="header-anchor" href="#_4-신입사원을-위한-실무-가이드" aria-label="Permalink to &quot;4. 신입사원을 위한 실무 가이드&quot;">​</a></h2><ul><li><strong>💡 왜 차수와 타입을 먼저 등록해야 하나요?</strong>: <ul><li>동호수(유닛)를 생성할 때 각 호실에 어떤 평형(타입)이 들어가는지 지정해야 하고, 분양가를 등록할 때도 차수와 타입, 층별 조건을 기준으로 가격표가 만들어지기 때문입니다. 따라서 <strong>[차수/타입 등록]은 프로젝트 분양 세팅의 가장 첫 관문</strong>입니다.</li></ul></li><li><strong>💡 타입 색상 지정 팁</strong>: <ul><li>59타입은 파란색 계열, 84타입은 주황색 계열 등 직관적으로 구분되는 색상을 지정해 두면, 향후 [계약 현황판]이나 [유닛 동호수 배치도]를 볼 때 분양 상담사나 고객에게 평형별 위치를 한눈에 안내하기 매우 편리합니다.</li></ul></li></ul>',14))])}const u=r(y,[["render",A]]);export{p as __pageData,u as default};
